import json,csv,html,os
D=os.path.dirname(__file__); SELL=6.6871; BUY=6.6591; MID=(SELL+BUY)/2
SRC=[
 ("S1","SAFE Tianjin FAQ 08 (2026-07-13)","https://www.safe.gov.cn/tianjin/2026/0713/3088.html","Foreign individual lawful current-account CNY income: ID + source docs incl. tax vouchers (Hui Fa[2020]14 Art.59)"),
 ("S2","SAFE Tianjin Case 9 (2024-06-21)","https://www.safe.gov.cn/tianjin/2024/0621/2529.html","Annual purchase facility only for Foreign Permanent Resident ID holders"),
 ("S3","SAFE Tianjin FAQ 10 (2026-09-17)","https://www.safe.gov.cn/tianjin/2026/0917/3134.html","Reconversion of unused RMB: original slip, 24 months; ≤$500/day, ≤$1,000 departure ID-only"),
 ("S4","Bank of China FX board 2026-11-11 20:39","https://www.boc.cn/sourcedb/whpj/","USD buy 665.91 / sell 668.71 per 100 USD; board is reference only, counter rate governs"),
 ("S5","Bank of China e-banking fee table (from 2014-11-01)","https://www.boc.cn/ebanking/service/cs1/200905/t20090506_990712.html","Cross-border wire 1‰ min CNY50 max CNY260 + cable CNY150 non-HK/Macau/Taiwan"),
 ("S6","IRS Foreign Tax Credit","https://www.irs.gov/individuals/international-taxpayers/foreign-tax-credit","Credit only vs US tax on same income; none on FEIE-excluded income; treaty-reduced amount only; 10-yr refund window"),
 ("S7","IRS FBAR (FinCEN 114)","https://www.irs.gov/businesses/small-businesses-self-employed/report-of-foreign-bank-and-financial-accounts-fbar","File if aggregate foreign accounts >$10,000 any time in year; Apr15/auto Oct15; penalties per 31 USC adjusted annually"),
 ("S8","26 USC 988 (2024 GPO ed.)","https://www.govinfo.gov/content/pkg/USCODE-2024-title26/html/USCODE-2024-title26-subtitleA-chap1-subchapN-partIII-subpartJ-sec988.htm","Disposition of nonfunctional currency is a §988 transaction; gain/loss = FX movement booking→payment"),
 ("S9","31 CFR 1010.821 eCFR (current to 2026-11-06)","https://www.ecfr.gov/current/title-31/subtitle-B/chapter-X/part-1010/subpart-H/section-1010.821","Authoritative but unofficial; FBAR penalty table — figures not republished here, read table directly"),
 ("S10","Wise Guide to CNY transfers","https://wise.com/help/articles/2955298/guide-to-cny-transfers","From-CNY: non-mainland, worked in China, tax record ≤3yrs, own account only, ≤CNY300k/bank-app transfer, fees in-app only"),
]
METHODS=[
 ("M01","Documented bank wire (lawful current-account income)","Lawful if documented","Assemble ID, employment/income proof, tax vouchers; bank purchases FX under S1; wire to own US account; keep slips","No $50k quota needed for documented income (S1); PR-ID holders may use facility (S2)","Quota myth; bank may reject incomplete docs; intermediary/receiving fees unpublished — blank","S1"),
 ("M02","Reconversion of previously exchanged unused RMB","Lawful, narrow","Show original exchange slip within 24 months; ≤$500/day or ≤$1,000 at departure ID-only","Only for RMB originally bought with FX","Not a general $500/day purchase right","S3"),
 ("M03","Wise from-CNY","Conditional","Verify (1-2d), upload ≤3yr tax record, own-account only, ≤CNY300k/transfer","Fee/limit set in-app — unpublished here, blank","Eligibility excludes mainland nationals; limit = after-tax salary","S10"),
 ("M04","Carry cash / ATM abroad","Limited","Declare >$10,000 (FinCEN 105 via CBP); PRC cash-carry & ATM caps apply — verify current cap at SAFE before use","Slow for large sums; card fees unpublished — blank","Not costed here; see flagged F4","S7"),
 ("M05","Splitting quota across people / underground FX / crypto","Unlawful — do not use","No steps provided. Listed only with penalties: Decree 532 fine bands & Yin Fa[2026]42 crypto illegality are in prior sections of this repo","—","30-100% fines, criminal exposure","S1"),
]
QUESTIONS=[("Q1","What is the source of the CNY (salary, property, inheritance, gift, business)?","Unknown — not provided","Determines SAFE document set & PRC tax","Request bank/SAFE document checklist in writing","S1"),("Q2","Was PRC tax withheld/paid, with vouchers?","Unknown","SAFE gate requires tax vouchers","Get tax payment certificate from employer/STA","S1"),("Q3","Do you hold a Foreign Permanent Resident ID?","Unknown","Only PR-ID holders get annual purchase facility","Check card type","S2"),("Q4","When was CNY acquired & USD basis (§988)?","Unknown","FX gain taxed; >$200 personal threshold in statute/prior sections","Reconstruct acquisition dates/rates","S8"),("Q5","US filing history: FBAR/8938 filed?","Unknown","Aggregate >$10k triggers FBAR","Review prior returns with CPA","S7"),("Q6","Written executable quote from your bank (rate+all fees)?","None obtained","Board rate is not executable (S4)","Ask bank for written all-in quote","S4")]
FLAGS=[("F1","Your bank/branch actual rate, wire & intermediary/receiving fees","Not published — blank","Get written quote"),("F2","Personal PRC/US tax amount","Not determined — facts Q1-Q5 unknown","CPA with documents"),("F3","HSBC/other bank tariff today","Not re-fetched this session — blank","Fetch tariff PDF dated today"),("F4","ATM/cash caps & card fees","Not re-read this session — blank","SAFE Hui Fa[2017]29 + card issuer"),("F5","FBAR penalty $ figures","eCFR authoritative-but-unofficial; read table, not republished","S9 link")]
def costs():
 rows=[]
 for t in range(10000,400001,10000):
  cny=t*SELL; fee_cny=min(max(cny*0.001,50),260)+150; fee=fee_cny/SELL; spread=t*(SELL/MID-1); rows.append({"usd":t,"cny":round(cny,2),"spread_usd":round(spread,2),"fee_usd":round(fee,2),"total_usd":round(spread+fee,2),"pct":round((spread+fee)/t*100,3)})
 return rows
C=costs()
def page(title,body):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — China2 verify 2026-11-11</title><style>body{{font-family:system-ui;margin:0;background:#f6f7f9;color:#111}}header,main{{max-width:1000px;margin:auto;padding:16px}}nav a{{margin-right:12px}}table{{border-collapse:collapse;width:100%;background:#fff;display:block;overflow-x:auto}}td,th{{border:1px solid #ddd;padding:7px;text-align:left;font-size:14px}}.card{{background:#fff;padding:14px;margin:10px 0;border-radius:8px}}</style></head><body><header><nav><a href="index.html">Summary</a><a href="methods.html">Methods</a><a href="costs.html">Costs $10k–$400k</a><a href="questions.html">Questions</a><a href="sources.html">Sources</a><a href="flagged.html">Flagged</a></nav><h1>{title}</h1></header><main>{body}</main></body></html>'
src={s[0]:s for s in SRC}
def sl(sid): s=src[sid]; return f'<a href="{s[2]}">{sid} {s[1]}</a>'
mile=[r for r in C if r["usd"] in (10000,50000,100000,200000,400000)]
idx=f'''<div class="card"><h2>Answer first</h2><p><b>Least-tax lawful route (if the money is documented, already-taxed current-account income):</b> one documented bank purchase+wire — no separate conversion excise was found in sources read today; cost is spread+fees, not a conversion tax. PRC tax, if owed, is on the underlying income and is the SAFE voucher gate (S1). US: FTC only against US tax on same income (S6); §988 FX gain may be taxable (S8); FBAR if aggregate &gt;$10,000 (S7). <b>Personal tax = not determined (Q1–Q5 unknown).</b></p></div><div class="card"><h2>Cost milestones — Bank of China published inputs, 2026-11-11</h2><table><tr><th>USD</th><th>Total est.</th><th>%</th><th>Source</th></tr>{''.join(f"<tr><td>${r['usd']:,}</td><td>${r['total_usd']:,.2f}</td><td>{r['pct']}%</td><td>{sl('S4')} {sl('S5')}</td></tr>" for r in mile)}</table><p>Estimate only: board sell {SELL}, mid {MID:.4f}; excludes intermediary/US receiving fees (F1, blank) and any tax.</p></div>'''
open(f"{D}/index.html","w").write(page("Executive summary — CNY→USD (verified 2026-11-11)",idx))
open(f"{D}/methods.html","w").write(page("All methods: pros, cons, steps",''.join(f'<div class="card"><h2>{m[0]} {html.escape(m[1])}</h2><p><b>Status:</b> {m[2]}</p><p><b>Steps:</b> {m[3]}</p><p><b>Pros:</b> {m[4]}</p><p><b>Cons/risks:</b> {m[5]}</p><p>{sl(m[6])}</p></div>' for m in METHODS)))
open(f"{D}/costs.html","w").write(page("Costs every $10,000 to $400,000 — BOC published inputs",f'<p>Formula: CNY=USD×{SELL}; spread=USD×(sell/mid−1); fee=(min(max(0.1% CNY,50),260)+150)/{SELL}. Intermediary/receiving = blank (F1).</p><table><tr><th>USD tier</th><th>CNY needed</th><th>Spread $</th><th>Wire fee $</th><th>Total est. $</th><th>%</th><th>Sources</th></tr>'+''.join(f"<tr><td>${r['usd']:,}</td><td>{r['cny']:,.2f}</td><td>{r['spread_usd']:,.2f}</td><td>{r['fee_usd']:,.2f}</td><td><b>{r['total_usd']:,.2f}</b></td><td>{r['pct']}</td><td>{sl('S4')} {sl('S5')}</td></tr>" for r in C)+"</table>"))
open(f"{D}/questions.html","w").write(page("Questions that must be answered first","<table><tr><th>#</th><th>Question</th><th>What we have</th><th>Why it matters</th><th>How to discover</th><th>Source</th></tr>"+''.join(f"<tr><td>{q[0]}</td><td>{q[1]}</td><td>{q[2]}</td><td>{q[3]}</td><td>{q[4]}</td><td>{sl(q[5])}</td></tr>" for q in QUESTIONS)+"</table>"))
open(f"{D}/sources.html","w").write(page("Official sources fetched 2026-11-11","<table><tr><th>ID</th><th>Source</th><th>What it says</th></tr>"+''.join(f'<tr><td>{s[0]}</td><td><a href="{s[2]}">{s[1]}</a></td><td>{s[3]}</td></tr>' for s in SRC)+"</table>"))
open(f"{D}/flagged.html","w").write(page("Flagged for Review — unverified (blank, not zero)",f"<p>Rule: blank = unverified, never zero. See {sl('S4')} {sl('S9')}</p><table><tr><th>ID</th><th>Item</th><th>Status</th><th>How to verify</th></tr>"+''.join(f"<tr><td>{f[0]}</td><td>{f[1]}</td><td>{f[2]}</td><td>{f[3]}</td></tr>" for f in FLAGS)+"</table>"))
json.dump({"sources":SRC,"methods":METHODS,"questions":QUESTIONS,"flags":FLAGS,"costs":C,"inputs":{"sell":SELL,"buy":BUY,"mid":MID}},open(f"{D}/data.json","w"),indent=1)
with open(f"{D}/costs.csv","w",newline="") as f: w=csv.DictWriter(f,fieldnames=C[0].keys()); w.writeheader(); w.writerows(C)
print(f"{len(C)} cost rows; $10k total ${C[0]['total_usd']} $400k total ${C[-1]['total_usd']}")
